// Sentientia LMS Live — trainer SSE client — Phase E.3.c.
//
// Opens EventSource(stream.php?sessionid&role=trainer). Listens for:
//   participant_joined  -> bump audience counter
//   participant_left    -> decrement audience counter
//   response_added      -> bump response counter for the current slide
//                          + dispatch DOM event for E.4 chart refresh
//   slide_changed       -> reload page (current slide changed via API)
//   session_ended       -> reload page (the End button on /trainer/end.php
//                          would have triggered this in another tab)
//
// All counter updates manipulate textContent of pre-existing elements;
// no innerHTML is used so this module is XSS-safe even if the server
// were to leak unescaped data into the SSE payload.
define('local_sentientia_live/trainer_sse', [], function() {
    'use strict';

    function init(opts) {
        opts = opts || {};
        var sessionid = opts.sessionid;
        var streamUrl = opts.streamUrl || '/local/sentientia_live/stream.php';

        if (!sessionid || typeof window.EventSource === 'undefined') {
            return;  // graceful degrade — page already shows current state on load
        }

        var url = streamUrl + '?sessionid=' + encodeURIComponent(sessionid)
            + '&role=trainer';

        var es;
        try {
            es = new EventSource(url, {withCredentials: true});
        } catch (e) {
            console.error('[sentientia_live] trainer EventSource failed', e);
            return;
        }

        es.addEventListener('error', function() {
            if (es.readyState === EventSource.CLOSED) {
                // Server rejected — silent failover; trainer's page is
                // still usable, just without live updates.
                console.warn('[sentientia_live] trainer SSE closed');
            }
        });

        // Audience count update — used for both joined + left.
        var updateAudienceCount = function(count) {
            var el = document.getElementById('sentientia-audience-count');
            if (el) {
                el.textContent = String(count);
            }
        };

        es.addEventListener('participant_joined', function(ev) {
            try {
                var data = JSON.parse(ev.data);
                if (typeof data.count_now === 'number') {
                    updateAudienceCount(data.count_now);
                }
            } catch (e) {}
        });

        es.addEventListener('participant_left', function(ev) {
            try {
                var data = JSON.parse(ev.data);
                if (typeof data.count_now === 'number') {
                    updateAudienceCount(data.count_now);
                }
            } catch (e) {}
        });

        es.addEventListener('response_added', function(ev) {
            try {
                var data = JSON.parse(ev.data);
                // Update visible response counter (textContent, safe).
                var counter = document.getElementById('sentientia-response-count');
                if (counter && typeof data.count_now === 'number') {
                    counter.textContent = String(data.count_now);
                }
                // Hand off to Phase E.4 result-panel module via DOM event.
                window.dispatchEvent(new CustomEvent(
                    'sentientia-live:response_added',
                    {detail: data}
                ));
            } catch (e) {}
        });

        es.addEventListener('slide_changed', function() {
            // Trainer might have advanced via the runner controls. Reload
            // to render the new current slide.
            window.location.reload();
        });

        es.addEventListener('session_ended', function() {
            window.location.reload();
        });

        es.addEventListener('reconnect', function() {
            // Browser auto-reconnects.
        });

        window.sentientiaLiveTrainerSSE = es;
    }

    return {
        init: init
    };
});
